#!/usr/bin/env python3
"""Verify source callback outcomes through predicate/result observations."""
import argparse,datetime,functools,importlib.util,json,re,shutil,subprocess,sys
from pathlib import Path
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[2]
spec=importlib.util.spec_from_file_location('common',ROOT/'formal/constraints/verify.py')
common=importlib.util.module_from_spec(spec);spec.loader.exec_module(common)
sha,run=common.sha,common.run
def closure(path):
    return cached_closure(path.resolve())

@functools.cache
def cached_closure(path):
    result={path}
    for name in re.findall(r'^include "([^"]+)"',path.read_text(),re.M):
        result.update(closure(path.parent/name))
    return result


def inventory(paths):
    declarations=[]
    for path in sorted(paths):
        text=path.read_text();module=re.search(r'^module (\w+)',text,re.M)[1]
        for m in re.finditer(r'^  (?:(?:ghost|opaque) )?(lemma|method|function|predicate|type)(?: \{:[^}]+\})* (\w+)(?:\(| =)',text,re.M):
            declarations.append({'name':module+'.'+m[2],'kind':m[1],'file':str(path.relative_to(ROOT))})
    return declarations


def check_dependencies(dafny,solc,sources,out):
    paths=['formal/abi/evidence/production-abi-correspondence/manifest.json', 'formal/collections/traversal/evidence/abstract-value-traversals/manifest.json', 'formal/collections/preparation/evidence/preparation-and-binding/manifest.json', 'formal/collections/callback-results/evidence/predicate-and-exhaustion/manifest.json', 'formal/collections/calls/evidence/callback-invocation-v2/manifest.json', 'formal/collections/wire/evidence/concrete-callback-wire/manifest.json', 'formal/collections/codec-state/evidence/canonical-prepared-state/manifest.json', 'formal/collections/constants/evidence/actual-constant-receipts/manifest.json', 'formal/collections/admission/evidence/arbitrary-descriptor-admission/manifest.json', 'formal/collections/codec-errors/evidence/concrete-codec-errors/manifest.json', 'formal/abi/outcomes/evidence/exact-recursive-outcomes/manifest.json', 'formal/collections/validation/evidence/validation-receipts/manifest.json', 'formal/collections/bound-call/evidence/concrete-bound-callback/manifest.json', 'formal/collections/repeated-call/evidence/repeated-source-callbacks/manifest.json']
    return common.check_dependencies(dafny, solc, sources, out, root=ROOT, here=HERE,
                                     paths=paths, inventory=inventory, closure=closure, hash_file=sha)


def inputs():
    deps=['contracts/Collections.sol','contracts/lib/AbiCodec.sol','formal/constraints/verify.py','formal/abi/toolchain.json']
    return sorted(closure(HERE/'Connection.dfy')|{f for f in HERE.iterdir() if f.is_file()}|{ROOT/p for p in deps})

def main():
    p=argparse.ArgumentParser();p.add_argument('--dafny',type=Path,required=True);p.add_argument('--solc',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
    out=a.output.resolve();out.mkdir(parents=True,exist_ok=False)
    dafny,solc=a.dafny.resolve(),a.solc.resolve();solver=dafny.parent/'z3/bin/z3-4.12.1'
    pin=json.loads((ROOT/'formal/abi/toolchain.json').read_text())
    if subprocess.check_output([str(dafny),'--version'],text=True).strip()!=pin['dafnyVersion']:raise ValueError('Unpinned Dafny')
    sources=closure(HERE/'Connection.dfy');files=inputs()
    if {p for p in HERE.glob('*.dfy') if not p.name.endswith('.template.dfy')}-sources:raise ValueError('Unreachable local proof')
    hashes={str(f.relative_to(ROOT)):sha(f) for f in files};snap=out/'source-snapshot'
    for f in files:
        dest=snap/f.relative_to(ROOT);dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(f,dest)
    source=snap/HERE.relative_to(ROOT)
    m={'status':'incomplete','scope':'Concrete callback outcomes projected into traversal call/predicate replies and optional result-validation receipts, exact failure precedence, canonical acceptance, and indexed source-record composition. Complete traversal scheduling and stop behavior after result failure remain open.','startedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'sourceSha256':hashes,'executableSha256':{k:sha(v) for k,v in [('dafny',dafny),('Dafny.dll',dafny.parent/'Dafny.dll'),('z3',solver),('solc',solc)]},'checks':[]}
    m['versions']={k:subprocess.check_output([str(v),'--version'],text=True).strip() for k,v in [('dafny',dafny),('z3',solver),('solc',solc)]}
    m['concreteTool']={'sha256':sha(Path(shutil.which('forge'))),'version':subprocess.check_output(['forge','--version'],text=True).strip()}
    m['assumptions']=['Typed callback outcomes come from the completed source call connection; FromRecord explicitly ties an indexed callback record to the exact source Run before applying the result adapter.', 'Room requires a uint256 descriptor length, representable operation/index/other/target, outer ErrorFits on callback failure, and actual returned-value validation Room only on the value-result path. Predicates require exactly canonical word 0 or 1 without codec descriptor validation.', 'Failed callbacks preserve exact outer error bytes and skip result validation. Value-result failures use operation/index/zero/target, whereas predicate errors retain the full predicate context. Descriptor errors retain codec parser errors.', 'Call replies and result checks are separate, preserving the raw successful value before result validation. Complete map/filter/fold selection, repeated result-check scheduling and first result-failure stopping remain caller obligations, not consequences of an unvalidated repeated-call record chain.', 'Source translation/compiler ABI, faithful context/offset projection, physical memory/resources and Dafny/Boogie/Z3 remain trusted. Proof-only composition reuses existing concrete/source-fault evidence; no new EVM/source-fault, bytecode, deployment or performance claim.']

    def save(): (out/'manifest.json').write_text(json.dumps(m,indent=2)+'\n')
    def record(name,command,timeout=1200):
        j=run(command,out/(name+'.log'),timeout);j.update(name=name,passed=j['exitCode']==0);m['checks'].append(j);save();return j
    save()
    m['checks'].append(check_dependencies(dafny,solc,sources,out));save()
    proof=record('proof',common.proof_command(dafny,source/'Connection.dfy',out/'proof.csv')+['--filter-symbol','CollectionsCallResults'])
    common.check_proof(proof,out/'proof.log',out/'proof.csv',inventory({f for f in sources if f.parent==HERE}))
    audit=record('audit',[dafny,'audit',source/'Connection.dfy']);audit['passed']=audit['passed'] and 'auditor completed with 0 findings' in (out/'audit.log').read_text()
    record('format',[dafny,'format','--check',*[f for f in source.glob('*.dfy') if not f.name.endswith('.template.dfy')]])
    m['inputsUnchanged']=hashes=={str(f.relative_to(ROOT)):sha(f) for f in inputs()}
    m['status']='passed' if m['inputsUnchanged'] and all(c['passed'] for c in m['checks']) else 'failed'
    m['completedAt']=datetime.datetime.now(datetime.timezone.utc).isoformat()
    shutil.rmtree(snap/'out',ignore_errors=True);shutil.rmtree(snap/'cache',ignore_errors=True)
    m['evidenceSha256']={str(f.relative_to(out)):sha(f) for f in sorted(out.rglob('*')) if f.is_file() and f.name!='manifest.json'}
    save();print(m['status']);raise SystemExit(0 if m['status']=='passed' else 1)

if __name__=='__main__':main()
